'use strict';
var tr=globalThis.YukioI18n?.t||(value=>value);
var uiLanguage=globalThis.YukioI18n?.language||'zh';
const $ = id => document.getElementById(id);
if(window.webkit?.messageHandlers?.yukio)document.documentElement.classList.add('in-panel');
const state = {client:'', archive:'0', group:null, groups:[], groupPage:null, page:null, epoch:0, revision:0, checking:false,catalog:[]};
const labels = {event_id:tr('记录依据编号'),evidence_id:tr('这项内容的依据编号'),sequence:tr('保存顺序'),source:tr('客户端'),source_id:tr('来源文件指纹'),generation:tr('观察版本'),source_line:tr('原记录行号'),source_offset:tr('原记录起点'),next_offset:tr('读取到的位置'),source_record_sha256:tr('原记录内容指纹'),source_fragment_sha256:tr('已越过片段的指纹'),kind:tr('原始活动类型'),source_kind:tr('客户端记录类型'),evidence_class:tr('证据类别'),session_id:tr('聊天编号'),agent_id:tr('助手编号'),is_sidechain:tr('协助分支标记'),thread_id:tr('聊天身份'),turn_id:tr('本轮编号'),context_turn_id:tr('所在轮次'),call_id:tr('操作编号'),item_id:tr('客户端条目编号'),tool_name:tr('工具名称'),association:tr('对应关系'),turn_association:tr('轮次对应依据'),outcome:tr('这次回执的结果'),call_outcome:tr('当时的操作结论'),projection_eligible:tr('对应关系可用于判断'),conflicting_results:tr('是否有冲突结果'),exit_code:tr('结束标记'),reported_status:tr('客户端报告状态'),reported_is_error:tr('客户端错误标记'),reported_ok:tr('客户端成功标记'),reported_interrupted:tr('客户端中断标记'),reported_await_user_response:tr('客户端等待用户标记'),background_task_reported:tr('客户端报告后台执行'),result_flags_conflict:tr('结果标记是否冲突'),request_evidence_id:tr('明确对应的请求依据'),after_gap_evidence_id:tr('前方缺口依据'),gap_evidence_id:tr('缺口依据'),gap_part:tr('缺口片段'),gap_start_offset:tr('缺口起点'),skipped_bytes:tr('这次越过的字节数'),total_record_bytes:tr('整条缺失记录的字节数'),record_complete:tr('是否已越过整条记录'),reason:tr('记录原因'),history_scope:tr('记录归属范围'),block_index:tr('消息内的位置'),timestamp_ms:tr('客户端时间标记'),timestamp_available:tr('是否有有效时间'),reported_stop_reason:tr('客户端停止标记')};
function el(tag,text,cls){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;}
function ago(stamp){if(!stamp)return '';const s=Math.max(0,Math.round((Date.now()-stamp)/1000));return s<60?tr('刚刚'):s<3600?Math.floor(s/60)+tr(' 分钟前'):s<86400?Math.floor(s/3600)+tr(' 小时前'):Math.floor(s/86400)+tr(' 天前');}
function short(value){return value ? value.length>18 ? value.slice(0,8)+'…'+value.slice(-6) : value : tr('未报告');}
function groupName(g){const match=state.catalog.find(c=>c.client===state.client&&c.session_id===g.session_id);if(match)return match.title;return !g.session_id||g.session_id.startsWith('source-') ? tr('尚未确认归属的记录') : tr('一段已保存的聊天');}
async function api(route,params={}){const r=await fetch('/api/'+route+'?'+new URLSearchParams(params),{headers:{'X-Yukio-Workbench':'1','X-Yukio-Language':uiLanguage},cache:'no-store'});if(!r.ok)throw new Error(tr('暂时无法读取。已有记录没有改变，请稍后刷新。'));return r.json();}
function error(e){$('error').hidden=false;$('error').textContent=e.message;}
function linkState(text,down=false){$('connection').textContent=text;$('connection').className='connection'+(down?' down':'');}
function connected(clearError=true){linkState(tr('已连接本机历史'));$('checked').textContent=new Date().toLocaleTimeString(uiLanguage==='en'?'en-US':'zh-CN',{hour:'2-digit',minute:'2-digit'});if(clearError)$('error').hidden=true;}
function proof(value,label=tr('查看这条说明的依据')){
 const d=el('details');d.append(el('summary',label));
 d.append(el('p',tr('已保留这条活动的来源和对应关系，原始记录不在这里直接展示。')));
 for(const key of ['reported_is_error','reported_ok','reported_interrupted','reported_await_user_response','conflicting_results'])
  if(typeof value[key]==='boolean')d.append(el('p',labels[key]+'：'+(value[key]?tr('是'):tr('否'))));
 return d;
}
function sub(item){const box=el('div',undefined,'sub');box.append(el('h4',item.title),el('p',item.note),el('small',item.evidence_label),proof(item.evidence));return box;}
function dateOf(ev){if(!ev.timestamp_available||!Number.isFinite(ev.timestamp_ms))return tr('时间未报告');const d=new Date(ev.timestamp_ms);return Number.isNaN(d.valueOf())?tr('时间无法确认'):d.toLocaleString(uiLanguage==='en'?'en-US':'zh-CN');}
function card(item,request){const box=el('article',undefined,'event '+item.tone),ev=item.evidence;const meta=el('div',undefined,'meta');meta.append(el('span',item.evidence_label,'tag'),el('span',dateOf(ev)));box.append(meta,el('h3',item.title),el('p',item.note));
 if(ev.after_gap_evidence_id)box.append(el('p',tr('前方有未读取的内容，不能把这段历史当作完整经过。')));
 for(const b of item.preview||[])box.append(sub(b));
 if(item.block_count){const details=el('details');details.append(el('summary',tr('查看消息中的全部 ')+item.block_count+tr(' 项记录')));const content=el('div'),more=el('button',tr('继续查看消息内容'),'blockMore');more.type='button';more.hidden=true;details.append(content,more);let offset=0,loading=false,loaded=false;async function load(){if(loading)return;loading=true;more.disabled=true;try{const data=await api('blocks',{...request,sequence:ev.sequence,offset});if(!loaded)content.replaceChildren();for(const b of data.items)content.append(sub(b));offset=data.next_offset;more.hidden=!data.has_more;loaded=true;}catch(e){content.append(el('p',e.message));}finally{loading=false;more.disabled=false;}}details.addEventListener('toggle',()=>{if(details.open&&!loaded)load();});more.onclick=load;box.append(details);}
 for(const r of item.relationships||[]){const names={belongs_to_root:tr('属于同一主聊天'),spawned_from:tr('由另一位助手派出'),forked_from:tr('从另一聊天分支而来'),parent_thread:tr('客户端报告的上级聊天')};box.append(el('p',(names[r.kind]||tr('客户端报告的关系')),'relation'),proof(r));}
 if(item.identity_issues?.length)box.append(el('p',tr('身份信息仍有未解决的问题，请查看依据。')),proof({reason:item.identity_issues.join(', ')}));
 box.append(window.YukioExplanation.controls({...request,sequence:ev.sequence}));box.append(proof(ev,tr('查看来源记录依据')));if(item.result)box.append(proof(item.result,tr('查看结果回执依据')));return box;}
function renderGroups(){const box=$('groups');box.replaceChildren();$('groupCount').textContent=state.groups.length+tr(' 份');if(!state.groups.length)box.append(el('p',state.archive==='1'?tr('尚无旧观察版本。'):tr('尚无已保存的会话记录。'),'empty'));for(const g of state.groups){const b=el('button');b.type='button';b.className='session';b.setAttribute('aria-pressed',String(g.key===state.group?.key));const known=state.catalog.find(c=>c.client===state.client&&c.session_id===g.session_id);b.title=groupName(g);b.append(el('strong',groupName(g)),el('span',[g.records+tr(' 条记录'),ago(known?.last_activity_ms),g.is_sidechain?tr('协助分支'):'',g.agent_id?tr('协助助手'):'',known?.project?.name].filter(Boolean).join(' · ')));b.onclick=()=>selectGroup(g);box.append(b);}$('moreGroups').hidden=!state.groupPage?.has_more;}
function notices(data){const box=$('notices');box.replaceChildren();if(data.archived)box.append(el('p',tr('正在查看旧观察版本，不能把这里的记录重复算作新进展。'),'notice'));if(data.source_notices.length){const d=el('details',undefined,'notice');d.append(el('summary',tr('这份来源有需要留意的记录（缺口、归属或文件变化）')));d.append(el('p',tr('以下提示覆盖整个来源文件，可能没有归属到当前聊天。')));for(const n of data.source_notices)d.append(el('p',n.title+tr(' · 保存 #')+n.evidence.sequence),proof(n.evidence));if(data.more_source_notices)d.append(el('p',tr('这里只列最近 20 条提示，完整记录仍保留在来源历史中。')));box.append(d);}}
async function selectGroup(g){window.YukioContext.clear();const epoch=++state.epoch;state.group=g;state.page=null;$('moreGroups').disabled=false;renderGroups();$('selectionLabel').textContent=state.archive==='1'?tr('旧观察版本'):tr('当前所选记录');$('selection').textContent=groupName(g);$('selectionNote').textContent=tr('最新保存的记录在前。结果是当时观察到的标记。');$('timeline').replaceChildren(el('p',tr('正在读取…'),'empty'));$('notices').replaceChildren();$('moreEvents').hidden=true;await loadTimeline(false,epoch);}
async function loadTimeline(append,epoch=state.epoch){const group=state.group;if(!group)return;const request={client:state.client,key:group.key};$('moreEvents').disabled=true;try{const data=await api('timeline',{...request,before:append?state.page.next_before:0,snapshot:append?state.page.snapshot:0});if(epoch!==state.epoch)return;state.page=data;if(!append){$('timeline').replaceChildren();notices(data);window.YukioContext.load({...request,snapshot:data.snapshot},g=>{state.archive='0';$('scope').value='0';selectGroup(g);});}for(const item of data.items)$('timeline').append(card(item,request));if(!append&&!data.items.length)$('timeline').append(el('p',tr('这份记录暂时没有可显示的内容。'),'empty'));$('moreEvents').hidden=!data.has_more;connected();}catch(e){if(epoch===state.epoch){error(e);if(!append)$('timeline').replaceChildren(el('p',tr('读取未完成，请重试。'),'empty'));}}finally{if(epoch===state.epoch)$('moreEvents').disabled=false;}}
async function loadGroups(append=false){const epoch=state.epoch;$('moreGroups').disabled=true;try{const page=await api('groups',{client:state.client,archive:state.archive,offset:append?state.groupPage.next_offset:0,snapshot:append?state.groupPage.snapshot:0});if(epoch!==state.epoch)return;state.groupPage=page;state.groups=append?state.groups.concat(page.groups):page.groups;renderGroups();connected();}catch(e){if(epoch===state.epoch)error(e);}finally{if(epoch===state.epoch)$('moreGroups').disabled=false;}}
async function change(){window.YukioContext.clear();++state.epoch;state.client=$('client').value;state.archive=$('scope').value;state.group=null;state.groups=[];state.page=null;state.groupPage=null;$('notices').replaceChildren();$('selection').textContent=tr('从左侧选择一份记录');$('selectionLabel').textContent=tr('等待选择');$('selectionNote').textContent=tr('最新保存的记录在前；保存顺序不等于实际执行先后。');$('timeline').replaceChildren(el('p',tr('选择一份记录后查看活动。'),'empty'));$('moreEvents').hidden=true;renderGroups();await loadGroups();}
async function refresh(){const epoch=++state.epoch;$('refresh').disabled=true;try{await loadGroups();if(epoch!==state.epoch)return;if(state.group)await loadTimeline(false,epoch);const clients=await api('clients');if(epoch!==state.epoch)return;state.revision=clients.clients.find(c=>c.id===state.client)?.revision||0;$('news').textContent='';}catch(e){error(e);}finally{$('refresh').disabled=false;}}
function recorderStatus(client){const r=client?.recorder||{state:'unavailable'};const names={active:tr('正在保存活动'),waiting:tr('记录器在等待新活动'),degraded:tr('部分来源暂时读不了'),paused_capacity:tr('保存空间达到上限，已暂停'),source_unavailable:tr('暂未找到来源目录'),stopped:tr('记录器已停止'),starting:tr('记录器正在启动'),failed:tr('记录器需要检查'),stale:tr('记录器状态已过期，暂不能确认是否运行'),unavailable:tr('没有可核对的记录器状态'),synthetic:tr('模拟记录，仅用于检查页面')};$('recorderStatus').textContent=(names[r.state]||names.unavailable)+(r.error_files?tr(' · 有 ')+r.error_files+tr(' 份来源读取异常'):'')+tr('。连接到历史不代表 AI 正在工作。');}
async function check(){if(state.checking||document.hidden)return;state.checking=true;try{const data=await api('clients');const client=data.clients.find(c=>c.id===state.client);recorderStatus(client);if(!client?.available){linkState(tr('当前历史暂时不可读取'),true);$('news').textContent=tr('请检查本机记录库，页面保留上次内容。');return;}connected(false);if(state.revision&&client.revision!==state.revision)$('news').textContent=tr('有新记录，点击刷新查看');if(!state.revision)state.revision=client.revision;}catch(e){linkState(tr('与本机服务的连接已断开'),true);$('news').textContent=tr('当前保留上次读取的内容。');}finally{state.checking=false;}}
$('client').onchange=()=>{state.revision=0;change().then(check);};$('scope').onchange=change;$('refresh').onclick=refresh;$('moreGroups').onclick=()=>loadGroups(true);$('moreEvents').onclick=()=>loadTimeline(true);
(async()=>{try{const data=await api('clients');try{state.catalog=(await api('current')).cards;}catch{}window.YukioExplanation.configure(data.explanation);if(data.mode==='synthetic'){document.querySelector('.local').textContent=tr('模拟活动 · 仅供检查');document.title=tr('Yukio · 模拟活动工作台');}for(const c of data.clients){const opt=el('option',c.name+(c.available?'':tr(' · 暂不可读取')));opt.value=c.id;$('client').append(opt);}connected();const query=new URLSearchParams(location.search);if([...$('client').options].some(o=>o.value===query.get('client')))$('client').value=query.get('client');await change();const target=state.groups.find(g=>g.key===query.get('key'));if(target)await selectGroup(target);await check();}catch(e){error(e);linkState(tr('未能读取本机历史'),true);}setInterval(check,10000);})();
